  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Eine neue Ruhe','آرامش تازه','Sara bemerkt Mias ruhigere Haltung; Mia erklärt ihre neue tägliche Routine.','سارا آرامش بیشتر میا را می‌بیند و میا روال تازه روزانه‌اش را توضیح می‌دهد.','story','mia-sara-b1-health-routine',17,56,180,1,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"notice-healthier-routine"}'); SET v_l_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,1,'character','Du wirkst heute viel ruhiger, Mia.','امروز خیلی آرام‌تر به نظر می‌رسی، میا.',56,NULL,NULL,NULL,NULL,'[{"surface":"Du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"wirkst","lemma":"wirken","translation":"به نظر رسیدن / جلوه کردن","partOfSpeech":"verb"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"viel","lemma":"viel","translation":"خیلی","partOfSpeech":"adverb"},{"surface":"ruhiger","lemma":"ruhig","translation":"آرام","partOfSpeech":"adjective","suffix":","},{"surface":"Mia","lemma":"Mia","translation":"میا (نام زنانه)","partOfSpeech":"proper_noun","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_1=LAST_INSERT_ID();
