  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Grenzen an stressigen Tagen','حد و مرز در روزهای پراسترس','Mia beschreibt, wie sie an stressigen Tagen auf ihren Körper hört und Grenzen setzt.','میا توضیح می‌دهد که در روزهای پراسترس چطور به بدنش گوش می‌دهد و حد تعیین می‌کند.','story','mia-sara-b1-health-routine',18,56,180,2,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"set-healthy-boundaries"}'); SET v_l_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,1,'character','Wie schaffst du das an stressigen Tagen?','در روزهای پراسترس چطور از پسش برمی‌آیی؟',56,NULL,NULL,NULL,NULL,'[{"surface":"Wie","lemma":"wie","translation":"چطور / چگونه","partOfSpeech":"adverb"},{"surface":"schaffst","lemma":"schaffen","translation":"از عهده برآمدن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"das","lemma":"das","translation":"این / آن","partOfSpeech":"pronoun"},{"surface":"an","lemma":"an","translation":"در / در روز","partOfSpeech":"preposition"},{"surface":"stressigen","lemma":"stressig","translation":"پراسترس","partOfSpeech":"adjective"},{"surface":"Tagen","lemma":"Tag","translation":"روز","partOfSpeech":"noun","suffix":"?"}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_7=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,2,'learner','Ich höre auf meinen Körper und sage auch mal Nein.','به بدنم گوش می‌دهم و گاهی هم نه می‌گویم.',56,NULL,NULL,'ich höre auf meinen körper und sage auch mal nein',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"höre","lemma":"hören","translation":"گوش دادن","partOfSpeech":"verb"},{"surface":"auf","lemma":"auf","translation":"روی / برای","partOfSpeech":"preposition"},{"surface":"meinen","lemma":"mein","translation":"مال من / من","partOfSpeech":"determiner"},{"surface":"Körper","lemma":"Körper","translation":"بدن","partOfSpeech":"noun"},{"surface":"und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"sage","lemma":"sagen","translation":"گفتن","partOfSpeech":"verb"},{"surface":"auch","lemma":"auch","translation":"هم / همچنین","partOfSpeech":"adverb"},{"surface":"mal","lemma":"Mal","translation":"بار","partOfSpeech":"noun"},{"surface":"Nein","lemma":"nein","translation":"نه","partOfSpeech":"interjection","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_8=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,3,'character','Ist das noch schwer für dich?','آیا این هنوز برایت سخت است؟',56,NULL,NULL,NULL,NULL,'[{"surface":"Ist","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"das","lemma":"das","translation":"این / آن","partOfSpeech":"pronoun"},{"surface":"noch","lemma":"noch","translation":"هنوز","partOfSpeech":"adverb"},{"surface":"schwer","lemma":"schwer","translation":"سخت","partOfSpeech":"adjective"},{"surface":"für","lemma":"für","translation":"برای","partOfSpeech":"preposition"},{"surface":"dich","lemma":"du","translation":"تو","partOfSpeech":"pronoun","suffix":"?"}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_9=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,4,'learner','Manchmal, aber ich setze klare Grenzen.','گاهی، اما حدهای روشنی تعیین می‌کنم.',56,NULL,NULL,'manchmal aber ich setze klare grenzen',NULL,'[{"surface":"Manchmal","lemma":"manchmal","translation":"گاهی","partOfSpeech":"adverb","suffix":","},{"surface":"aber","lemma":"aber","translation":"اما","partOfSpeech":"conjunction"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"setze","lemma":"setzen","translation":"گذاشتن / قرار دادن","partOfSpeech":"verb"},{"surface":"klare","lemma":"klar","translation":"روشن / مشخص","partOfSpeech":"adjective"},{"surface":"Grenzen","lemma":"Grenze","translation":"مرز / حد","partOfSpeech":"noun","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_10=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,5,'character','Und was machst du nach der Arbeit?','و بعد از کار چه می‌کنی؟',56,NULL,NULL,NULL,NULL,'[{"surface":"Und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"was","lemma":"was","translation":"چی / چه","partOfSpeech":"pronoun"},{"surface":"machst","lemma":"machen","translation":"انجام دادن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"nach","lemma":"nach","translation":"پس از / به","partOfSpeech":"preposition"},{"surface":"der","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Arbeit","lemma":"Arbeit","translation":"کار","partOfSpeech":"noun","suffix":"?"}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_11=LAST_INSERT_ID();
