  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Schlaf und kleine Veränderungen','خواب و تغییرهای کوچک','Sara und Mia prüfen, wie Schlaf und Getränke Mias Energie beeinflussen.','سارا و میا بررسی می‌کنند که خواب و نوشیدنی‌ها چطور بر انرژی میا اثر می‌گذارند.','story','mia-sara-b1-health-routine',19,56,180,3,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"observe-small-changes"}'); SET v_l_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,1,'character','Schläfst du inzwischen auch besser?','حالا بهتر هم می‌خوابی؟',56,NULL,NULL,NULL,NULL,'[{"surface":"Schläfst","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"inzwischen","lemma":"inzwischen","translation":"تا حالا / اکنون","partOfSpeech":"adverb"},{"surface":"auch","lemma":"auch","translation":"هم / همچنین","partOfSpeech":"adverb"},{"surface":"besser","lemma":"besser","translation":"بهتر","partOfSpeech":"adverb","suffix":"?"}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_13=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,2,'learner','Ja, ich gehe früher in das Bett und stehe ruhiger auf.','بله، زودتر به تخت می‌روم و آرام‌تر بیدار می‌شوم.',56,NULL,NULL,'ja ich gehe früher in das bett und stehe ruhiger auf',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"gehe","lemma":"gehen","translation":"رفتن","partOfSpeech":"verb"},{"surface":"früher","lemma":"früh","translation":"زودتر","partOfSpeech":"adverb"},{"surface":"in","lemma":"in","translation":"در / داخل","partOfSpeech":"preposition"},{"surface":"das","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Bett","lemma":"Bett","translation":"تخت","partOfSpeech":"noun"},{"surface":"und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"stehe","lemma":"aufstehen","translation":"از خواب بلند شدن","partOfSpeech":"verb"},{"surface":"ruhiger","lemma":"ruhig","translation":"آرام","partOfSpeech":"adjective"},{"surface":"auf","lemma":"aufstehen","translation":"از خواب بلند شدن","partOfSpeech":"verb","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_14=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,3,'character','Trinkst du abends noch Kaffee?','شب‌ها هنوز قهوه می‌نوشی؟',56,NULL,NULL,NULL,NULL,'[{"surface":"Trinkst","lemma":"trinken","translation":"نوشیدن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"abends","lemma":"abends","translation":"عصرها / شب ها","partOfSpeech":"adverb"},{"surface":"noch","lemma":"noch","translation":"هنوز","partOfSpeech":"adverb"},{"surface":"Kaffee","lemma":"Kaffee","translation":"قهوه","partOfSpeech":"noun","suffix":"?"}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_15=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,4,'learner','Nein, ich trinke lieber Tee oder Wasser.','نه، ترجیح می‌دهم چای یا آب بنوشم.',56,NULL,NULL,'nein ich trinke lieber tee oder wasser',NULL,'[{"surface":"Nein","lemma":"nein","translation":"نه","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"trinke","lemma":"trinken","translation":"نوشیدن","partOfSpeech":"verb"},{"surface":"lieber","lemma":"lieber","translation":"ترجیحاً","partOfSpeech":"adverb"},{"surface":"Tee","lemma":"Tee","translation":"چای","partOfSpeech":"noun"},{"surface":"oder","lemma":"oder","translation":"یا","partOfSpeech":"conjunction"},{"surface":"Wasser","lemma":"Wasser","translation":"آب","partOfSpeech":"noun","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_16=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,5,'character','Das klingt wirklich vernünftig.','این واقعاً منطقی به نظر می‌رسد.',56,NULL,NULL,NULL,NULL,'[{"surface":"Das","lemma":"das","translation":"این / آن","partOfSpeech":"pronoun"},{"surface":"klingt","lemma":"klingen","translation":"به نظر رسیدن","partOfSpeech":"verb"},{"surface":"wirklich","lemma":"wirklich","translation":"واقعا","partOfSpeech":"adverb"},{"surface":"vernünftig","lemma":"vernünftig","translation":"منطقی","partOfSpeech":"adjective","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_17=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,6,'learner','Ich merke, dass kleine Veränderungen viel bewirken.','متوجه می‌شوم که تغییرهای کوچک تأثیر زیادی دارند.',56,NULL,NULL,'ich merke dass kleine veränderungen viel bewirken',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"merke","lemma":"merken","translation":"متوجه شدن","partOfSpeech":"verb","suffix":","},{"surface":"dass","lemma":"dass","translation":"که","partOfSpeech":"conjunction"},{"surface":"kleine","lemma":"klein","translation":"کوچک","partOfSpeech":"adjective"},{"surface":"Veränderungen","lemma":"Veränderung","translation":"تغییر","partOfSpeech":"noun"},{"surface":"viel","lemma":"viel","translation":"خیلی","partOfSpeech":"adverb"},{"surface":"bewirken","lemma":"bewirken","translation":"باعث شدن / اثر گذاشتن","partOfSpeech":"verb","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_18=LAST_INSERT_ID();
