  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Der Plan bleibt freundlich','برنامه با مهربانی ادامه دارد','Mia plant bewusste Pausen und bleibt geduldig, wenn eine Gewohnheit einmal nicht klappt.','میا برای استراحت آگاهانه برنامه می‌ریزد و وقتی عادتی پیش نمی‌رود با خودش صبور می‌ماند.','story','mia-sara-b1-health-routine',20,56,180,4,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"keep-self-care-plan"}'); SET v_l_4=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,1,'character','Welche Gewohnheit möchtest du nicht ändern?','کدام عادت را نمی‌خواهی تغییر بدهی؟',56,NULL,NULL,NULL,NULL,'[{"surface":"Welche","lemma":"welche","translation":"کدام / چه","partOfSpeech":"pronoun"},{"surface":"Gewohnheit","lemma":"Gewohnheit","translation":"عادت","partOfSpeech":"noun"},{"surface":"möchtest","lemma":"möchten","translation":"خواستن / مایل بودن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"adverb"},{"surface":"ändern","lemma":"ändern","translation":"تغییر دادن","partOfSpeech":"verb","suffix":"?"}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_19=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,2,'learner','Ich möchte jeden Tag bewusst eine Pause machen.','می‌خواهم هر روز آگاهانه استراحت کنم.',56,NULL,NULL,'ich möchte jeden tag bewusst eine pause machen',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"möchte","lemma":"möchten","translation":"خواستن / مایل بودن","partOfSpeech":"verb"},{"surface":"jeden","lemma":"jeder","translation":"هر","partOfSpeech":"determiner"},{"surface":"Tag","lemma":"Tag","translation":"روز","partOfSpeech":"noun"},{"surface":"bewusst","lemma":"bewusst","translation":"آگاهانه","partOfSpeech":"adverb"},{"surface":"eine","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"Pause","lemma":"Pause","translation":"استراحت","partOfSpeech":"noun"},{"surface":"machen","lemma":"machen","translation":"انجام دادن","partOfSpeech":"verb","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_20=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,3,'character','Und wenn dein Plan einmal nicht klappt?','و اگر برنامه‌ات یک بار پیش نرفت؟',56,NULL,NULL,NULL,NULL,'[{"surface":"Und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"wenn","lemma":"wenn","translation":"اگر / وقتی","partOfSpeech":"conjunction"},{"surface":"dein","lemma":"dein","translation":"مال تو / تو","partOfSpeech":"determiner"},{"surface":"Plan","lemma":"Plan","translation":"برنامه","partOfSpeech":"noun"},{"surface":"einmal","lemma":"einmal","translation":"یک بار","partOfSpeech":"adverb"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"adverb"},{"surface":"klappt","lemma":"klappen","translation":"خوب پیش رفتن","partOfSpeech":"verb","suffix":"?"}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_21=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,4,'learner','Dann bin ich geduldig mit mir und fange neu an.','آن وقت با خودم صبورم و از نو شروع می‌کنم.',56,NULL,NULL,'dann bin ich geduldig mit mir und fange neu an',NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"bin","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"geduldig","lemma":"geduldig","translation":"صبور","partOfSpeech":"adjective"},{"surface":"mit","lemma":"mit","translation":"با","partOfSpeech":"preposition"},{"surface":"mir","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"fange","lemma":"anfangen","translation":"شروع کردن","partOfSpeech":"verb"},{"surface":"neu","lemma":"neu","translation":"جدید / تازه","partOfSpeech":"adjective"},{"surface":"an","lemma":"anfangen","translation":"شروع کردن","partOfSpeech":"verb","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_22=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,5,'character','Das ist eine gesunde Einstellung.','این یک نگرش سالم است.',56,NULL,NULL,NULL,NULL,'[{"surface":"Das","lemma":"das","translation":"این / آن","partOfSpeech":"pronoun"},{"surface":"ist","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"eine","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"gesunde","lemma":"gesund","translation":"سالم","partOfSpeech":"adjective"},{"surface":"Einstellung","lemma":"Einstellung","translation":"نگرش","partOfSpeech":"noun","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_23=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,6,'learner','Genau, ich passe jetzt besser auf mich auf.','دقیقاً، حالا بهتر مراقب خودم هستم.',56,NULL,NULL,'genau ich passe jetzt besser auf mich auf',NULL,'[{"surface":"Genau","lemma":"genau","translation":"دقیقا","partOfSpeech":"adverb","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"passe","lemma":"aufpassen","translation":"مراقب بودن","partOfSpeech":"verb"},{"surface":"jetzt","lemma":"jetzt","translation":"حالا / اکنون","partOfSpeech":"adverb"},{"surface":"besser","lemma":"besser","translation":"بهتر","partOfSpeech":"adverb"},{"surface":"auf","lemma":"auf","translation":"روی / برای","partOfSpeech":"preposition"},{"surface":"mich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"auf","lemma":"aufpassen","translation":"مراقب بودن","partOfSpeech":"verb","suffix":"."}]','Über Selbstfürsorge und Gewohnheiten sprechen','قیدها و جمله‌های وابسته برای توصیف عادت‌های سالم به کار می‌روند؛ بخش‌های جداشدنی فعل نیز جداگانه نگاشت می‌شوند.','{"focus":"self_care_routine","structures":["adverbial detail","dass clause","wenn clause","separable verbs"]}','{"cefr":"B1","course":"de-fa","series":105}'); SET v_t_24=LAST_INSERT_ID();
